98	void RaylibRenderer::beginFrame(const CameraPose& pose) {
99	    camera_.position = {pose.position.x, pose.position.y + 1.7f, pose.position.z};
100	    const float pitchRad = degToRad(pose.pitchDeg);
101	    const float yawRad = degToRad(pose.yawDeg);
102	    const Vector3 dir{std::sin(yawRad) * std::cos(pitchRad), std::sin(pitchRad),
103	                      std::cos(yawRad) * std::cos(pitchRad)};
104	    camera_.target = {camera_.position.x + dir.x, camera_.position.y + dir.y,
105	                      camera_.position.z + dir.z};
106	    camera_.up = {0.f, 1.f, 0.f};
107	    camera_.fovy = 70.f;
108	    camera_.projection = CAMERA_PERSPECTIVE;
109	    BeginMode3D(camera_);
110	}
