112	void RaylibRenderer::drawCity(const City& city) {
113	    const float half = city.halfSize();
114	
115	    // Ground: grass base with asphalt street strips and block slabs on top.
116	    DrawPlane({0.f, 0.f, 0.f}, {half * 2.f, half * 2.f}, kGrass);
117	    for (const float c : {-kStreetCenter, kStreetCenter}) {
118	        DrawCube({c, 0.02f, 0.f}, kStreetWidth, 0.04f, half * 2.f, kAsphalt);
119	        DrawCube({0.f, 0.02f, c}, half * 2.f, 0.04f, kStreetWidth, kAsphalt);
120	    }
121	    // Block slabs: plaza (center) is pale stone, park (north-east) stays
122	    // grass, every other block gets a sidewalk-toned slab.
123	    for (const float bx : {-64.f, 0.f, 64.f}) {
124	        for (const float bz : {-64.f, 0.f, 64.f}) {
125	            const bool plaza = bx == 0.f && bz == 0.f;
126	            const bool park = bx == 64.f && bz == 64.f;
127	            if (park) continue;
128	            DrawCube({bx, 0.04f, bz}, 48.f, 0.08f, 48.f, plaza ? kPlaza : kSidewalk);
129	        }
130	    }
131	
132	    // Street furniture (traffic lights, bushes) renders through the same
133	    // buildings pass below — City authors their positions AND colliders,
134	    // so nothing visible can be walk-through.
135	
136	    // Buildings and street props from the collision AABBs — the models scale
137	    // to fit the authoritative footprints, never the other way around.
138	    for (const Building& b : city.buildings()) {
139	        // The fountain is composed from primitives (no pack model). Must be
140	        // dispatched by id BEFORE the model lookup: modelForBuilding falls
141	        // back to a hashed generic building for uncurated ids.
142	        if (b.id == "fountain") {
143	            drawFountain(b, assets_.sizeSpecFor(b).worldHeight);
144	            continue;
145	        }
146	        if (const Model* model = assets_.modelForBuilding(b)) {
147	            const Assets::SizeSpec& spec = assets_.sizeSpecFor(b);
148	            if (spec.mode == Assets::SizeSpec::Mode::Uniform) {
149	                drawModelUniform(*model, (b.minX + b.maxX) * 0.5f,
150	                                 (b.minZ + b.maxZ) * 0.5f, spec.worldHeight, WHITE);
151	            } else {
152	                drawModelFittedToAABB(*model, b.minX, b.minZ, b.maxX, b.maxZ, b.height,
153	                                      WHITE);
154	            }
155	        } else {
156	            // Fallback primitive, tinted like the legacy renderer's boxes.
157	            const unsigned char tint =
158	                static_cast<unsigned char>(120 + (b.facadeKind * 37) % 90);
159	            const Vector3 center{(b.minX + b.maxX) * 0.5f, b.height * 0.5f,
160	                                 (b.minZ + b.maxZ) * 0.5f};
161	            DrawCube(center, b.maxX - b.minX, b.height, b.maxZ - b.minZ,
162	                     Color{tint, tint, static_cast<unsigned char>(tint + 20), 255});
163	            DrawCubeWires(center, b.maxX - b.minX, b.height, b.maxZ - b.minZ,
164	                          Color{40, 45, 60, 255});
165	        }
166	    }
167	}
