169	void RaylibRenderer::drawCharacter(const CharacterVisual& visual) {
170	    const Assets::CharacterAsset* character =
171	        assets_.characterFor(visual.variantSeed, visual.police);
172	    if (!character) {
173	        // No pack: marker cylinder, same as the pre-asset placeholder.
174	        const Vec3& p = visual.position;
175	        DrawCylinder({p.x, 0.f, p.z}, 0.35f, 0.35f, 1.8f, 12, Color{200, 120, 80, 255});
176	        DrawCylinderWires({p.x, 0.f, p.z}, 0.35f, 0.35f, 1.8f, 12, Color{60, 30, 20, 255});
177	        return;
178	    }
179	
180	    // Pick the clip: death overrides everything, gestures interrupt,
181	    // then walk/idle by movement.
182	    int clip = visual.walking ? character->walk : character->idle;
183	    if (visual.gesturePhase > 0.f && character->gesture >= 0) clip = character->gesture;
184	    if (visual.dead && character->death >= 0) clip = character->death;
185	
186	    AnimState& state = anim_[visual.variantSeed];
187	    if (state.clip != clip) {
188	        state.clip = clip;
189	        state.time = 0.f;
190	    }
191	    state.time += GetFrameTime();
192	    if (clip >= 0 && clip < character->clipCount) {
193	        // raylib bakes glTF animations at ~60 samples/second; loop by frame.
194	        const ModelAnimation& animation = character->clips[clip];
195	        const int frame =
196	            static_cast<int>(state.time * 60.f) % (animation.frameCount > 0
197	                                                       ? animation.frameCount
198	                                                       : 1);
199	        // CPU skinning on the shared model right before this entity's draw,
200	        // so several entities can reuse one model with different clocks.
201	        UpdateModelAnimation(character->model, animation, frame);
202	    }
203	
204	    // Uniform height: scale so every character stands ~1.8 units tall, feet
205	    // on the ground, rotated to the game's facing convention (0 → +Z).
206	    const BoundingBox bb = GetModelBoundingBox(character->model);
207	    const float modelHeight = bb.max.y - bb.min.y;
208	    const float s = modelHeight > 0.f ? 1.8f / modelHeight : 1.f;
209	    const Vector3 position{visual.position.x, -bb.min.y * s, visual.position.z};
210	    DrawModelEx(character->model, position, Vector3{0.f, 1.f, 0.f}, visual.facingDeg,
211	                Vector3{s, s, s}, WHITE);
212	
213	    // Non-neutral moods float as an emote above the head — the same six
214	    // procedural faces the legacy renderer painted on, now billboarded.
215	    // The dead don't emote.
216	    if (!visual.dead && visual.face != NpcFace::Neutral) {
217	        DrawBillboard(camera_, assets_.faceTexture(visual.face),
218	                      Vector3{visual.position.x, 2.45f, visual.position.z}, 0.55f,
219	                      WHITE);
220	    }
221	}
