223	void RaylibRenderer::drawViewmodel(int weaponKind, float attackFraction) {
224	    // Per-weapon visuals live in this table; adding a WeaponKind means
225	    // adding a row, never a new code branch. Sizes are camera-space meters.
226	    struct ViewSpec {
227	        Vector3 size;        // main body (fist / gun body)
228	        Color color;
229	        float thrust;        // + pushes forward on attack (punch), - recoils
230	        bool grip;           // draw a pistol-style grip under the body
231	    };
232	    static const ViewSpec kSpecs[] = {
233	        {{0.11f, 0.09f, 0.14f}, Color{224, 172, 138, 255}, 0.45f, false},  // Fist
234	        {{0.05f, 0.07f, 0.30f}, Color{55, 58, 66, 255}, -0.14f, true},     // Pistol
235	    };
236	    const int count = static_cast<int>(sizeof(kSpecs) / sizeof(kSpecs[0]));
237	    if (weaponKind < 0 || weaponKind >= count) return;
238	    const ViewSpec& spec = kSpecs[weaponKind];
239	
240	    // Camera basis for a lower-right anchored prop.
241	    const Vector3 fwd{camera_.target.x - camera_.position.x,
242	                      camera_.target.y - camera_.position.y,
243	                      camera_.target.z - camera_.position.z};
244	    const float flen = std::sqrt(fwd.x * fwd.x + fwd.y * fwd.y + fwd.z * fwd.z);
245	    if (flen < 1e-4f) return;
246	    const Vector3 f{fwd.x / flen, fwd.y / flen, fwd.z / flen};
